def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    bob_bid = None
    cindy_bid = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if agent_id == 'Bob':
                    bob_bid = bid
                elif agent_id == 'Cindy':
                    cindy_bid = bid

    if not alive:
        return min(budget, 20.0)

    seats = supply / float(WATER_REQ)
    tight = seats < 2.0

    target = 55.5
    if bob_bid is not None:
        target = bob_bid + 1.6
    elif prev_bids:
        target = min(max(prev_bids) + 1.0, 62.0)

    if cindy_bid is not None and cindy_bid > 100:
        target = min(target, 58.0)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if tight:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        bid = max(target + 4.0, 66.0)
    elif urgency >= 3:
        bid = max(target + 1.0, 58.0)
    elif urgency >= 1:
        bid = max(target - 1.0, 52.0)
    else:
        bid = 34.0 if tight else 28.0

    if budget < 120:
        bid = min(bid, 0.55 * budget)
    elif budget < 200:
        bid = min(bid, 0.7 * budget)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 68.0))

    if len(alive) == 1:
        only_id = alive[int(0)][0]
        if only_id == 'Cindy':
            bid = 25.0 if hp > 3 and no_water_days == 0 else 60.0
        else:
            bid = max(bid, 56.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-aware aggressiveness: with supply near 25, we can afford to bid a bit more
    # but still avoid overpaying.
    supply_ratio = 0.0
    try:
        supply_ratio = (float(supply) - 15.0) / (25.0 - 15.0)
    except Exception:
        supply_ratio = 0.5
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Determine target multiplier based on yesterday aggressiveness
    # Alex/Cindy yesterday show bids around ~94-113; use that as a signal.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base_mult = 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        base_mult = 0.62
    else:
        base_mult = 0.52

    # If our HP is low, we must secure water more reliably.
    hp = float(my_status.get('hp', 0.0))
    if hp <= 2.0:
        base_mult += 0.25
    elif hp <= 4.0:
        base_mult += 0.12

    # Slightly scale with supply_ratio (more supply -> can bid slightly more)
    mult = base_mult + 0.08 * supply_ratio

    # Convert to bid; keep within budget and avoid bidding above salary cap too often.
    bid = DAILY_SALARY * mult

    # Safety: never bid negative; never exceed budget.
    if bid < 0.0:
        bid = 0.0

    budget = float(my_status.get('budget', 0.0))
    bid = min(bid, budget)

    return float(bid)

