        base_bid = max(base_bid, DAILY_SALARY * 1.05) 
    elif my_hp <= 4: 
        base_bid = max(base_bid, DAILY_SALARY * 0.9) 
    elif my_hp <= 6: 
        base_bid = max(base_bid, DAILY_SALARY * 0.75) 

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2: 
        base_bid = max(base_bid, DAILY_SALARY * 1.1) 
